use download_engine::{DownloadJob, Engine, EngineError, HttpEngine, ProcessLimits};
use miarina_mdm_adapter::MdmEngine;
use std::{sync::Arc, time::Duration};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::TcpListener,
};
use tokio_util::sync::CancellationToken;

// Generated bytes only: exercise real HTTP ranges without external media/services.
async fn server(slow: bool) -> (String, Arc<Vec<u8>>, tokio::task::JoinHandle<()>) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("http://{}/test.mp4", listener.local_addr().unwrap());
    let bytes = Arc::new(
        (0..4 * 1024 * 1024)
            .map(|i| (i % 251) as u8)
            .collect::<Vec<_>>(),
    );
    let data = bytes.clone();
    let task = tokio::spawn(async move {
        loop {
            let (mut socket, _) = listener.accept().await.unwrap();
            let data = data.clone();
            tokio::spawn(async move {
                let mut request = Vec::new();
                let mut buf = [0; 1024];
                while !request.ends_with(b"\r\n\r\n") {
                    let n = socket.read(&mut buf).await.unwrap_or(0);
                    if n == 0 || request.len() > 16384 {
                        return;
                    }
                    request.extend_from_slice(&buf[..n]);
                }
                let text = String::from_utf8_lossy(&request).to_ascii_lowercase();
                let range = text.lines().find_map(|l| l.strip_prefix("range: bytes="));
                let (start, end) = range
                    .map(|r| {
                        let (a, b) = r.trim().split_once('-').unwrap();
                        (
                            a.parse::<usize>().unwrap(),
                            b.parse::<usize>()
                                .unwrap_or(data.len() - 1)
                                .min(data.len() - 1),
                        )
                    })
                    .unwrap_or((0, data.len() - 1));
                let status = if range.is_some() {
                    "206 Partial Content"
                } else {
                    "200 OK"
                };
                let content_range = if range.is_some() {
                    format!("Content-Range: bytes {start}-{end}/{}\r\n", data.len())
                } else {
                    String::new()
                };
                let header = format!(
                    "HTTP/1.1 {status}\r\nContent-Length: {}\r\nContent-Type: video/mp4\r\nAccept-Ranges: bytes\r\nETag: \"fixture-v1\"\r\n{content_range}Connection: close\r\n\r\n",
                    end - start + 1
                );
                if socket.write_all(header.as_bytes()).await.is_err() || text.starts_with("head ") {
                    return;
                }
                for chunk in data[start..=end].chunks(4096) {
                    if slow {
                        tokio::time::sleep(Duration::from_millis(20)).await;
                    }
                    if socket.write_all(chunk).await.is_err() {
                        break;
                    }
                }
            });
        }
    });
    (url, bytes, task)
}

fn job(url: &str, dir: &std::path::Path) -> DownloadJob {
    DownloadJob {
        url: media_core::validate_media_url(url).unwrap(),
        part_path: dir.join("test.part"),
        dest_dir: dir.into(),
        file_name: "test.mp4".into(),
        progress_interval: Duration::from_millis(10),
        format_id: None,
        process: ProcessLimits {
            concurrent_fragments: 4,
            ..Default::default()
        },
    }
}

#[tokio::test]
async fn segmented_transfer_preserves_existing_destination() {
    let (url, bytes, server) = server(false).await;
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("test.mp4"), b"keep me").unwrap();
    let engine = MdmEngine::new(HttpEngine::new().unwrap());
    let out = tokio::time::timeout(
        Duration::from_secs(15),
        engine.download(&job(&url, dir.path()), &|_| {}, CancellationToken::new()),
    )
    .await
    .unwrap()
    .unwrap();
    assert_eq!(std::fs::read(out.final_path).unwrap(), *bytes);
    assert_eq!(
        std::fs::read(dir.path().join("test.mp4")).unwrap(),
        b"keep me"
    );
    assert_eq!(out.bytes, bytes.len() as u64);
    server.abort();
}

#[tokio::test]
async fn canceled_transfer_resumes_to_exact_bytes() {
    let (url, bytes, server) = server(true).await;
    let dir = tempfile::tempdir().unwrap();
    let engine = MdmEngine::new(HttpEngine::new().unwrap());
    let job = job(&url, dir.path());
    let cancel = CancellationToken::new();
    let progress = |p: download_engine::Progress| {
        if p.downloaded > 0 {
            cancel.cancel();
        }
    };
    let first = tokio::time::timeout(
        Duration::from_secs(15),
        engine.download(&job, &progress, cancel.clone()),
    )
    .await
    .unwrap();
    assert!(matches!(first, Err(EngineError::Canceled)), "{first:?}");
    assert!(!dir.path().join("test.mp4").exists());
    let out = tokio::time::timeout(
        Duration::from_secs(15),
        engine.download(&job, &|_| {}, CancellationToken::new()),
    )
    .await
    .unwrap()
    .unwrap();
    assert_eq!(std::fs::read(out.final_path).unwrap(), *bytes);
    server.abort();
}

#[tokio::test]
async fn precanceled_transfer_leaves_no_files() {
    let dir = tempfile::tempdir().unwrap();
    let engine = MdmEngine::new(HttpEngine::new().unwrap());
    let cancel = CancellationToken::new();
    cancel.cancel();
    assert!(matches!(
        engine
            .download(
                &job("https://example.com/test.mp4", dir.path()),
                &|_| {},
                cancel
            )
            .await,
        Err(EngineError::Canceled)
    ));
    assert_eq!(std::fs::read_dir(dir.path()).unwrap().count(), 0);
}

#[tokio::test]
async fn existing_sequential_partial_uses_legacy_resume() {
    let (url, bytes, server) = server(false).await;
    let dir = tempfile::tempdir().unwrap();
    let job = job(&url, dir.path());
    std::fs::write(&job.part_path, &bytes[..8192]).unwrap();
    let engine = MdmEngine::new(HttpEngine::new().unwrap());
    let out = tokio::time::timeout(
        Duration::from_secs(15),
        engine.download(&job, &|_| {}, CancellationToken::new()),
    )
    .await
    .unwrap()
    .unwrap();
    assert_eq!(std::fs::read(out.final_path).unwrap(), *bytes);
    assert!(!download_engine::ytdlp::work_dir(&job.part_path).exists());
    server.abort();
}

#[tokio::test]
async fn mismatched_resume_state_is_rejected_without_touching_files() {
    let dir = tempfile::tempdir().unwrap();
    let job = job("http://127.0.0.1:1/test.mp4", dir.path());
    let work = download_engine::ytdlp::work_dir(&job.part_path);
    std::fs::create_dir_all(&work).unwrap();
    let target = work.join("transfer.bin");
    let wrong = url::Url::parse("https://example.com/different.mp4").unwrap();
    let state = mdm_engine::state::ResumeState::new(
        wrong.clone(),
        wrong,
        target.clone(),
        100,
        Default::default(),
    );
    state
        .write(&mdm_engine::state::state_path(&target))
        .unwrap();
    let part = mdm_engine::naming::part_path(&target);
    std::fs::write(&part, b"keep partial").unwrap();
    let engine = MdmEngine::new(HttpEngine::new().unwrap());
    assert!(matches!(
        engine
            .download(&job, &|_| {}, CancellationToken::new())
            .await,
        Err(EngineError::Unsupported { .. })
    ));
    assert_eq!(std::fs::read(part).unwrap(), b"keep partial");
}
